async function hydrateItemPhotos(root=el('itemsGrid')){await Promise.all([...root.querySelectorAll('img[data-local-photo],img[data-storage-photo]')].map(async image=>{const item=state.items.find(entry=>entry.id===image.dataset.localPhoto||entry.photo===`storage:${image.dataset.storagePhoto}`);try{let url=image.dataset.localPhoto?await getLocalPhotoUrl(image.dataset.localPhoto):null;if(!url&&item?.photo?.startsWith('storage:')){url=await signedPhotoUrl(item.photo.slice(8));if(session?.user){const response=await fetch(url);if(response.ok){await storeLocalPhotoBlob(item.id,await response.blob());item.photoLocal=true;localStorage.setItem(KEY,JSON.stringify(state));url=await getLocalPhotoUrl(item.id)}}}if(url&&image.isConnected)image.src=url}catch(error){console.error('Não foi possível carregar uma foto:',error)}}))}
async function preparePhotosForSync(){if(!session?.user)return;for(const item of state.items){let blob;if(item.photo?.startsWith('data:image/')){blob=await(await fetch(item.photo)).blob();await saveLocalPhoto(item.id,item.photo);item.photoLocal=true}else if(item.photo?.startsWith('local-photo:')){blob=await getLocalPhotoBlob(item.id);if(!blob)throw new Error(`A cópia local da foto de "${item.name}" não foi encontrada.`)}if(!blob)continue;const path=`${session.user.id}/${item.id}/${crypto.randomUUID()}.jpg`,{error}=await supabaseClient.storage.from(PHOTO_BUCKET).upload(path,blob,{contentType:'image/jpeg',upsert:false});if(error)throw new Error(`Não foi possível enviar a foto de "${item.name}": ${error.message}`);item.photo=`storage:${path}`;item.photoLocal=true}try{localStorage.setItem(KEY,JSON.stringify(state))}catch(error){console.error('Não foi possível atualizar o cache local das fotos:',error)}}
async function setPhotoPreview(value){if(!value){el('photoPreview').removeAttribute('src');el('photoPreview').classList.add('hidden');el('photoPlaceholder').classList.remove('hidden');el('removePhoto').classList.add('hidden');return}el('photoPreview').classList.remove('hidden');el('photoPlaceholder').classList.add('hidden');el('removePhoto').classList.remove('hidden');const item=state.items.find(entry=>entry.id===el('itemId').value);if(value.startsWith('local-photo:')||value.startsWith('storage:')&&item?.photoLocal){try{const local=typeof item?.photoLocal==='string'&&item.photoLocal.startsWith('data:image/')?item.photoLocal:await getLocalPhotoUrl(item?.id||value.slice(12));if(local&&photoData===value){el('photoPreview').src=local;return}}catch(error){console.error('Não foi possível carregar a cópia local da foto:',error)}}if(value.startsWith('storage:')){el('photoPreview').removeAttribute('src');try{const url=await signedPhotoUrl(value.slice(8));if(photoData===value)el('photoPreview').src=url}catch(error){notify('Não foi possível carregar a foto armazenada na nuvem.')}}else if(value.startsWith('local-photo:'))el('photoPreview').removeAttribute('src');else el('photoPreview').src=value}function itemCard(i){const quantity=itemQuantity(i),low=i.minimum!==''&&quantity<=Number(i.minimum),exp=i.expiry?Math.ceil((new Date(i.expiry+'T00:00:00')-new Date(new Date().setHours(0,0,0,0)))/86400000):null;let pill=i.type==='Beleza'?'Beauty':i.type==='Remédios'?'Medicine':'';const latest=[...(i.purchases||[])].sort((a,b)=>(b.date||'').localeCompare(a.date||''))[0],purchase=latest?`<div class="item-meta item-purchase"><span>Última compra</span><b>${fmtDate(latest.date)||'Data não informada'}${latest.value!==''&&latest.value!=null&&Number.isFinite(Number(latest.value))?' · '+Number(latest.value).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}):''}</b></div>`:'',restock=quantity<=0?`<div class="restock-choice" role="group" aria-label="Decisão de reposição para ${escapeHtml(i.name)}"><button type="button" data-restock="${escapeHtml(i.id)}" data-decision="repor" aria-pressed="${i.restockDecision==='repor'}" class="${i.restockDecision==='repor'?'selected':''}">Repor</button><button type="button" data-restock="${escapeHtml(i.id)}" data-decision="nao-repor" aria-pressed="${i.restockDecision==='nao-repor'}" class="${i.restockDecision==='nao-repor'?'selected':''}">Não repor</button></div>`:'',content=i.content?`<span class="item-quick-value" aria-label="Conteúdo: ${escapeHtml(i.content)}">${escapeHtml(i.content)}</span>`:'';return `<article class="item-card"><div class="item-photo">${itemPhotoHtml(i)}</div><div class="item-head"><div class="item-name" title="${escapeHtml(i.name)}">${escapeHtml(i.name)}</div><button class="dots-btn" data-edit="${escapeHtml(i.id)}" aria-label="Editar ${escapeHtml(i.name)}">···</button></div><span class="type-pill ${pill}">${escapeHtml(i.type)}${i.category?' · '+escapeHtml(i.category):''}</span><div class="item-stock-info ${quantity<=0?'has-restock':''}"><div class="item-quick-values ${i.content?'has-content':''}"><span class="item-quick-value ${quantity<=0?'zero':''}" aria-label="Quantidade: ${escapeHtml(quantity)} ${escapeHtml(i.unit)}">${escapeHtml(quantity)} ${escapeHtml(i.unit)}</span>${content}</div><div class="item-detail-values"><span aria-label="Local: ${escapeHtml(i.place)}">${escapeHtml(i.place)}</span>${i.brand?`<span aria-label="Marca: ${escapeHtml(i.brand)}">${escapeHtml(i.brand)}</span>`:''}</div>${restock}</div>${purchase}<div class="item-footer"><span class="${exp!==null&&exp<=30?'expiry-warn':''}">${i.expiry?(exp<0?'Vencido em ':exp===0?'Vence hoje · ':'Validade · ')+fmtDate(i.expiry):'Sem validade informada'}</span>${low?'<span class="low-badge">ESTOQUE BAIXO</span>':''}</div></article>`}async function setRestockDecision(id,decision){const item=state.items.find(entry=>entry.id===id);if(!item||itemQuantity(item)>0||!['repor','nao-repor'].includes(decision)||item.restockDecision===decision)return;Object.assign(item,editedItem(item,{restockDecision:decision}));renderItems();const saved=await persist();notify(saved?'Decisão salva e sincronizada.':'Decisão salva neste aparelho. A sincronização será retomada quando possível.')}
function openItem(item){el('itemForm').reset();el('itemId').value=item?.id||'';el('modalTitle').textContent=item?'Editar item':'Adicionar item';el('itemName').value=item?.name||'';el('itemType').value=item?.type||'Despensa';el('itemQuantity').value=item?.quantity??0;el('itemUnit').value=item?.unit||'unidade(s)';el('itemMinimum').value=item?.minimum??'';el('itemExpiry').value=item?.expiry||'';el('itemBrand').value=item?.brand||'';el('itemContent').value=item?.content||'';el('itemNotes').value=item?.notes||'';purchaseDraft=(item?.purchases||[]).map(p=>({...p}));editingPurchaseIndex=null;manualQuantityDraft=purchaseDraft.length?'0':String(item?.quantity??0);el('itemQuantity').readOnly=purchaseDraft.length>0;updateQuantityField();const today=new Date();el('purchaseDate').value=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`;el('purchaseQuantity').value=1;renderFilters();el('itemCategory').value=item?.category||'';el('itemPlace').value=item?.place||state.places[0];photoData=item?.photo||'';setPhoto();renderPurchaseHistory();const actions=el('itemForm').querySelector('.modal-actions');let del=el('deleteItem');if(del)del.remove();if(item){del=document.createElement('button');del.type='button';del.id='deleteItem';del.className='secondary-btn';del.style.marginRight='auto';del.textContent='Excluir item';del.onclick=async()=>{if(confirm(`Excluir “${item.name}”?`)){markDeleted('items',item.id);state.items=state.items.filter(i=>i.id!==item.id);try{await deleteLocalPhoto(item.id)}catch(error){console.error('Não foi possível remover a cópia local da foto:',error)}persist();render();closeItem();notify('Item excluído')}};actions.prepend(del)}el('modalOverlay').classList.remove('hidden');el('itemName').focus()}
