el('itemForm').addEventListener('submit',async e=>{e.preventDefault();if(!applyPurchaseEdit())return;const submitButton=el('itemForm').querySelector('[type="submit"]');submitButton.disabled=true;try{const existingId=el('itemId').value,id=existingId||crypto.randomUUID(),old=state.items.find(item=>item.id===existingId),now=nextItemTimestamp(old);let photo=photoData,photoLocal=old?.photoLocal||false;if(photoData.startsWith('data:image/')){await saveLocalPhoto(id,photoData);photo=`local-photo:${id}`;photoLocal=true}else if(photoData!==old?.photo){photoLocal=photoData.startsWith('local-photo:')}const item={id,name:el('itemName').value.trim(),type:el('itemType').value,category:el('itemCategory').value,place:el('itemPlace').value,quantity:purchaseDraft.length?String(availablePurchaseQuantity(purchaseDraft)):el('itemQuantity').value,unit:el('itemUnit').value,content:el('itemContent').value.trim(),minimum:el('itemMinimum').value,expiry:el('itemExpiry').value,brand:el('itemBrand').value.trim(),notes:el('itemNotes').value.trim(),photo,photoLocal,restockDecision:(purchaseDraft.length?availablePurchaseQuantity(purchaseDraft):Number(el('itemQuantity').value))>0?'':old?.restockDecision||'',purchases:purchaseDraft.map(p=>({...p,quantity:purchaseQuantity(p)})),_localPending:true,createdAt:old?.createdAt||now,updatedAt:now};clearDeleted('items',id);state.items=old?state.items.map(current=>current.id===id?item:current):[item,...state.items];const saving=persist();render();closeItem();const synced=await saving,savedItem=state.items.find(current=>current.id===id);notify(synced&&savedItem?.type===item.type&&savedItem?.category===item.category?(old?'Item atualizado e sincronizado':'Item adicionado e sincronizado'):'Alteração salva neste aparelho; sincronização pendente.')}catch(error){console.error('Falha ao salvar o item:',error);notify(error.message||'Não foi possível salvar o item.')}finally{submitButton.disabled=false}});
function renderPurchaseHistory(){
  const list=el('purchaseHistory');
  if(!list)return;
  const entries=purchaseDraft.map((purchase,index)=>({purchase,index})).sort((a,b)=>(b.purchase.date||'').localeCompare(a.purchase.date||''));
  list.innerHTML=entries.length?entries.map(({purchase,index})=>{
    const amounts=purchaseAmounts(purchase),unit=escapeHtml(el('itemUnit').value),value=purchase.value!==''&&purchase.value!=null&&Number.isFinite(Number(purchase.value))?Number(purchase.value).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}):'Valor não informado';
    const editor=editingPurchaseIndex===index?`<div class="purchase-editor" data-purchase-editor="${index}"><div class="purchase-edit-grid"><label class="field">Data<input data-purchase-edit="date" type="date" value="${escapeHtml(purchase.date||'')}"></label><label class="field">Registro<select data-purchase-edit="kind"><option value="compra"${purchase.kind!=='reposicao'?' selected':''}>Compra inicial</option><option value="reposicao"${purchase.kind==='reposicao'?' selected':''}>Reposição</option></select></label><label class="field">Quantidade comprada<input data-purchase-edit="quantity" type="number" min="0.01" step="any" value="${amounts.total}"></label><label class="field">Ainda existe<input data-purchase-edit="remaining" type="number" min="0" step="any" value="${amounts.remaining}"></label><label class="field">Já acabou<input data-purchase-edit="finished" type="number" min="0" step="any" value="${amounts.finished}"></label><label class="field">Valor pago (R$) · opcional<input data-purchase-edit="value" type="number" min="0" step="any" value="${purchase.value==null?'':escapeHtml(purchase.value)}"></label></div><div class="purchase-edit-actions"><small>Depois, toque em Salvar item para sincronizar.</small><button type="button" class="secondary-btn" data-cancel-purchase="${index}">Cancelar</button><button type="button" class="primary-btn" data-save-purchase="${index}">Aplicar</button></div></div>`:'';
    return `<div class="purchase-row"><div><div class="purchase-head"><b>${fmtDate(purchase.date)||'Data não informada'}</b></div><small>${purchase.kind==='reposicao'?'Reposição':'Compra inicial'} · ${amounts.total} ${unit}</small><small>Ainda existe: ${amounts.remaining} · Já acabou: ${amounts.finished}${amounts.unassigned?' · Não informado: '+amounts.unassigned:''}</small></div><strong>${value}</strong><div class="purchase-row-actions"><button type="button" data-edit-purchase="${index}" aria-label="Editar compra">Editar</button><button type="button" data-remove-purchase="${index}" aria-label="Remover compra">×</button></div>${editor}</div>`;
  }).join(''):'<p class="purchase-empty">Nenhuma compra registrada para este item.</p>';
}
function applyPurchaseEdit(){
  if(editingPurchaseIndex===null)return true;
  const editor=el('purchaseHistory').querySelector(`[data-purchase-editor="${editingPurchaseIndex}"]`),purchase=purchaseDraft[editingPurchaseIndex];
  if(!editor||!purchase)return false;
  const field=name=>editor.querySelector(`[data-purchase-edit="${name}"]`).value;
  const date=field('date'),quantity=Number(field('quantity')),remaining=Number(field('remaining')),finished=Number(field('finished')),value=field('value');
  if(!date)return notify('Informe a data da compra.'),false;
  if(![quantity,remaining,finished].every(Number.isFinite)||quantity<=0||remaining<0||finished<0)return notify('Informe quantidades válidas.'),false;
  if(remaining+finished>quantity+0.000001)return notify('“Ainda existe” e “Já acabou” não podem ultrapassar a quantidade comprada.'),false;
  if(value!==''&&(!Number.isFinite(Number(value))||Number(value)<0))return notify('Informe um valor válido ou deixe o preço em branco.'),false;
  Object.assign(purchase,{date,kind:field('kind'),quantity,remainingQuantity:remaining,finishedQuantity:finished,value:value===''?'':Number(value),status:remaining>0?'available':finished>=quantity?'finished':''});
  editingPurchaseIndex=null;updateQuantityField();renderPurchaseHistory();return true;
}
el('addPurchaseBtn').onclick=()=>{if(!applyPurchaseEdit())return;const date=el('purchaseDate').value,value=el('purchaseValue').value,quantity=Number(el('purchaseQuantity').value);if(!date)return notify('Informe a data da compra.');if(value!==''&&(!Number.isFinite(Number(value))||Number(value)<0))return notify('Informe um valor válido ou deixe o preço em branco.');if(!Number.isFinite(quantity)||quantity<=0)return notify('Informe uma quantidade comprada maior que zero.');const available=el('purchaseStatus').value==='available';purchaseDraft.push({id:crypto.randomUUID(),date,value:value===''?'':Number(value),quantity,remainingQuantity:available?quantity:0,finishedQuantity:available?0:quantity,kind:el('purchaseKind').value,status:el('purchaseStatus').value});updateQuantityField();el('purchaseValue').value='';el('purchaseQuantity').value='1';el('purchaseStatus').value='available';renderPurchaseHistory()};
el('purchaseHistory').addEventListener('click',event=>{
  const button=event.target.closest('[data-edit-purchase],[data-remove-purchase],[data-save-purchase],[data-cancel-purchase]');if(!button)return;
  if(button.hasAttribute('data-save-purchase'))return applyPurchaseEdit();
  if(button.hasAttribute('data-cancel-purchase')){editingPurchaseIndex=null;renderPurchaseHistory();return}
  if(button.hasAttribute('data-edit-purchase')){if(!applyPurchaseEdit())return;editingPurchaseIndex=Number(button.dataset.editPurchase);renderPurchaseHistory();return}
  const index=Number(button.dataset.removePurchase);if(editingPurchaseIndex!==null&&editingPurchaseIndex!==index&&!applyPurchaseEdit())return;
  if(confirm('Remover este registro de compra? A quantidade em estoque será recalculada.')){purchaseDraft.splice(index,1);editingPurchaseIndex=null;updateQuantityField();renderPurchaseHistory()}
});
