async function blobToDataUrl(blob){return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(blob)})}
 el('exportBtn').onclick=async()=>{try{const backup=JSON.parse(JSON.stringify(state));for(const item of backup.items){if(item.photoLocal===true||item.photo?.startsWith('storage:')||item.photo?.startsWith('local-photo:')){let photoBlob=await getLocalPhotoBlob(item.id);if(!photoBlob&&item.photo?.startsWith('storage:')){const url=await signedPhotoUrl(item.photo.slice(8)),response=await fetch(url);if(response.ok)photoBlob=await response.blob()}if(!photoBlob)throw new Error(`Não foi possível incluir a foto de "${item.name}" no backup.`);item.photo=await blobToDataUrl(photoBlob)}delete item.photoLocal}const blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='casa-em-ordem-backup.json';a.click();URL.revokeObjectURL(a.href);notify('Backup baixado')}catch(error){notify(error.message||'Não foi possível incluir as fotos no backup.')}};

const syncConfig=window.DESPENSA_SUPABASE||{};
const recordId=syncConfig.recordId||'principal';
let supabaseClient=null,session=null,remoteSaving=false,remoteSavePending=false,syncStatus='offline',syncMessage='Entre na conta para sincronizar';
function setSyncStatus(ok,msg){syncStatus=ok===true?'online':ok===false?'offline':ok;syncMessage=msg;const title=el('syncTitle'),subtitle=el('syncSubtitle'),dot=document.querySelector('.sync-dot');if(title)title.textContent=syncStatus==='online'?'Sincronizado':syncStatus==='syncing'?'Sincronizando':'Dados neste aparelho';if(subtitle)subtitle.textContent=msg;if(dot)dot.style.background=syncStatus==='online'?'#74a97b':syncStatus==='error'?'#c77861':'#d4a65d';const detail=el('syncDetailsStatus'),last=el('syncDetailsLast'),account=el('syncDetailsAccount');if(detail)detail.textContent=msg;if(last)last.textContent=formatSyncDate(localStorage.getItem(LAST_SYNC_KEY));if(account)account.textContent=session?.user?.email||'Não conectado'}
function formatSyncDate(value){if(!value)return 'Ainda não sincronizado';const date=new Date(value);return Number.isNaN(date.valueOf())?'Ainda não sincronizado':date.toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})}
function configureSupabase(){if(supabaseClient)return true;if(!window.supabase?.createClient||!syncConfig.url||!syncConfig.anonKey){setSyncStatus('error','Supabase não configurado');return false}supabaseClient=window.supabase.createClient(syncConfig.url,syncConfig.anonKey);return true}
async function initializeSync(){if(!configureSupabase())return;setSyncStatus('syncing','Verificando sessão e dados da nuvem...');try{const {data,error}=await supabaseClient.auth.getSession();if(error)throw error;session=data.session;if(session?.user)await connectSync();else setSyncStatus('offline','Entre na conta para sincronizar')}catch(error){session=null;setSyncStatus('error',error.message||'Falha ao conectar com o Supabase');console.error('Falha ao iniciar o Supabase:',error)}}
function remoteState(row){if(!row?.data)return null;const remote=row.data,types=Array.isArray(remote.types)?remote.types:Object.keys({...DEFAULT_CATEGORIES,...remote.categories});return {...remote,items:(remote.items||[]).map(item=>({...item,purchases:Array.isArray(item.purchases)?item.purchases:[]})),places:mergePlaces(remote.places),types,categories:mergeCategories(remote.categories,types),syncMeta:normalizeSyncMeta(remote.syncMeta),updatedAt:remote.updatedAt||row.updated_at||null}}
async function readRemoteRow(){const {data,error}=await supabaseClient.from(syncConfig.table||'home_inventory').select('data,updated_at').eq('user_id',session.user.id).eq('id',recordId).maybeSingle();if(error)throw error;return data}
function syncSnapshot(){return {...state,items:state.items.map(({photoLocal,_localPending,...item})=>item),syncMeta:normalizeSyncMeta(state.syncMeta)}}
function stableStringify(value){if(Array.isArray(value))return '['+value.map(stableStringify).join(',')+']';if(value&&typeof value==='object')return '{'+Object.keys(value).filter(key=>value[key]!==undefined).sort().map(key=>JSON.stringify(key)+':'+stableStringify(value[key])).join(',')+'}';return JSON.stringify(value)}
function verifySavedSnapshot(row,snapshot){const stored=row?.data;if(!stored||stored.updatedAt!==snapshot.updatedAt||stableStringify(stored)!==stableStringify(snapshot))throw new Error('O Supabase não confirmou exatamente os dados enviados. A alteração permanece pendente neste aparelho.')}
async function cleanupDeletedPhotos(){for(const itemId of Object.keys(normalizeSyncMeta(state.syncMeta).deleted.items)){if(state.items.some(item=>item.id===itemId))continue;const folder=`${session.user.id}/${itemId}`,storage=supabaseClient.storage.from(PHOTO_BUCKET),{data,error}=await storage.list(folder,{limit:100});if(error)throw error;if(data?.length){const {error:removeError}=await storage.remove(data.map(file=>`${folder}/${file.name}`));if(removeError)throw removeError}}}
async function connectSync(){if(!configureSupabase()||!session?.user)return false;setSyncStatus('syncing','Lendo e mesclando os dados dos aparelhos...');try{const row=await readRemoteRow(),remote=remoteState(row),owner=localStorage.getItem('casa-em-ordem-sync-owner');if(owner&&owner!==session.user.id){try{localStorage.setItem(`${KEY}-account-${owner}`,JSON.stringify(state))}catch(error){console.error('Não foi possível arquivar o cache da conta anterior:',error)}state=remote||{items:[],places:START_PLACES,types:Object.keys(DEFAULT_CATEGORIES),categories:DEFAULT_CATEGORIES,syncMeta:{deleted:{}},updatedAt:null};render()}else if(remote){state=mergeInventory(state,remote);render()}try{localStorage.setItem(KEY,JSON.stringify(state));localStorage.setItem(PENDING_KEY,session.user.id)}catch(error){console.error('Não foi possível manter o cache local antes da sincronização:',error)}const saved=await syncPush();if(saved)setSyncStatus('online','Dados mesclados e confirmados no Supabase');return saved}catch(error){setSyncStatus('error',error.message||'Falha ao ler os dados do Supabase');console.error('Falha ao sincronizar inventário:',error);notify(error.message||'Confira a tabela e as políticas do Supabase.');return false}}
async function syncPush(){if(!configureSupabase()||!session?.user)return false;if(remoteSaving){remoteSavePending=true;while(remoteSaving)await new Promise(resolve=>setTimeout(resolve,25));return await syncPush()}remoteSaving=true;setSyncStatus('syncing','Mesclando e salvando alterações...');try{do{remoteSavePending=false;let committed=false;for(let attempt=0;attempt<6&&!committed;attempt++){const revisionAtStart=stateRevision,row=await readRemoteRow(),remote=remoteState(row);if(remote){state=mergeInventory(state,remote);render()}await preparePhotosForSync();const timestamp=new Date(Math.max(Date.now(),(new Date(row?.updated_at||0).getTime()||0)+1)).toISOString();state.updatedAt=timestamp;const snapshot=syncSnapshot(),payload={user_id:session.user.id,id:recordId,data:snapshot,updated_at:timestamp};try{localStorage.setItem(KEY,JSON.stringify(state));localStorage.setItem(PENDING_KEY,session.user.id)}catch(error){console.error('Não foi possível manter o cache local antes da gravação:',error)}let result;if(row)result=await supabaseClient.from(syncConfig.table||'home_inventory').update({data:snapshot,updated_at:timestamp}).eq('user_id',session.user.id).eq('id',recordId).eq('updated_at',row.updated_at).select('data,updated_at').maybeSingle();else result=await supabaseClient.from(syncConfig.table||'home_inventory').insert(payload).select('data,updated_at').maybeSingle();if(result.error?.code==='23505')continue;if(result.error)throw result.error;if(!result.data)continue;verifySavedSnapshot(result.data,snapshot);committed=true;if(stateRevision!==revisionAtStart)remoteSavePending=true;else state.items.forEach(item=>{delete item._localPending});try{localStorage.setItem(KEY,JSON.stringify(state))}catch(error){console.error('Não foi possível atualizar o cache local após a gravação:',error)}}if(!committed)throw new Error('Os dados mudaram em outro aparelho durante a gravação. Tente sincronizar novamente.')}while(remoteSavePending);try{await cleanupDeletedPhotos()}catch(error){console.error('Não foi possível remover fotos de itens excluídos:',error)}try{localStorage.removeItem(PENDING_KEY);localStorage.setItem('casa-em-ordem-sync-owner',session.user.id)}catch(error){console.error('Não foi possível atualizar o estado local da sincronização:',error)}const syncedAt=new Date().toISOString();try{localStorage.setItem(LAST_SYNC_KEY,syncedAt)}catch(error){console.error('Não foi possível registrar o horário da sincronização:',error)}setSyncStatus('online','Sincronização confirmada');return true}catch(error){try{localStorage.setItem(PENDING_KEY,session.user.id)}catch{}setSyncStatus('error',`Pendente: ${error.message||'falha ao salvar'}`);console.error('Falha ao salvar inventário no Supabase:',error);notify(`A alteração ficou guardada neste aparelho, mas não foi confirmada na nuvem: ${error.message||'falha de conexão'}`);return false}finally{remoteSaving=false}}
function settingsLegacy(){el('simpleEyebrow').textContent='PREFERÊNCIAS';el('simpleTitle').textContent='Sincronização e conta';const logged=Boolean(session?.user);el('simpleContent').innerHTML=`<div class="setting-block"><h3>Sincronização entre aparelhos</h3><p>O inventário é mesclado entre os aparelhos conectados à mesma conta. As alterações também ficam neste navegador enquanto aguardam a confirmação do Supabase.</p><div class="sync-details-grid"><div><small>ESTADO</small><b id="syncDetailsStatus">${escapeHtml(syncMessage)}</b></div><div><small>ÚLTIMA CONFIRMAÇÃO</small><b id="syncDetailsLast">${formatSyncDate(localStorage.getItem(LAST_SYNC_KEY))}</b></div><div><small>CONTA</small><b id="syncDetailsAccount">${escapeHtml(session?.user?.email||'Não conectado')}</b></div></div>${logged?`<div class="sync-panel-actions"><button class="primary-btn" id="syncNowBtn">Sincronizar agora</button><button class="secondary-btn" id="syncDownloadBtn">Baixar e mesclar</button><button class="secondary-btn" id="syncSendBtn">Enviar alterações</button><button class="secondary-btn" id="sbLogout">Sair da conta</button></div>`:`<input class="setting-input" id="sbEmail" type="email" autocomplete="email" placeholder="Seu e-mail"><input class="setting-input" id="sbPass" type="password" autocomplete="current-password" placeholder="Senha"><div class="modal-actions" style="margin-top:12px"><button class="secondary-btn" id="sbSignup">Criar conta</button><button class="primary-btn" id="sbLogin">Entrar e sincronizar</button></div>`}</div><div class="setting-block"><h3>Backup e fotos</h3><p>Use o botão de download no topo para guardar uma cópia. As fotos novas são armazenadas no Supabase Storage; configure o bucket do guia SQL para sincronizá-las.</p></div>`;el('simpleOverlay').classList.remove('hidden');setSyncStatus(syncStatus,syncMessage);if(logged){el('syncNowBtn').onclick=async()=>{await connectSync();settings()};el('syncDownloadBtn').onclick=async()=>{await connectSync();settings()};el('syncSendBtn').onclick=async()=>{if(!confirm('Vou mesclar os dados deste aparelho com a nuvem antes de confirmar o envio. Continuar?'))return;await connectSync();settings()};el('sbLogout').onclick=async()=>{try{const {error}=await supabaseClient.auth.signOut();if(error)throw error;session=null;setSyncStatus('offline','Entre na conta para sincronizar');settings()}catch(error){notify(error.message||'Não foi possível desconectar.')}}}else{el('sbSignup').onclick=async()=>{if(!configureSupabase())return;const email=el('sbEmail').value.trim(),password=el('sbPass').value;if(!email||!password)return notify('Preencha seu e-mail e sua senha.');try{const {data,error}=await supabaseClient.auth.signUp({email,password,options:{emailRedirectTo:location.origin+location.pathname}});if(error)throw error;if(data.session){session=data.session;await connectSync();settings()}else notify('Conta criada. Confirme o e-mail e depois entre.')}catch(error){notify(error.message||'Não foi possível criar a conta.')}};el('sbLogin').onclick=async()=>{if(!configureSupabase())return;const email=el('sbEmail').value.trim(),password=el('sbPass').value;if(!email||!password)return notify('Preencha seu e-mail e sua senha.');try{const {data,error}=await supabaseClient.auth.signInWithPassword({email,password});if(error)throw error;session=data.session;await connectSync();settings()}catch(error){notify(error.message||'Não foi possível entrar.')}}}}
function syncPanel(){el('simpleEyebrow').textContent='SINCRONIZAÇÃO';el('simpleTitle').textContent='Status entre aparelhos';const logged=Boolean(session?.user),pending=localStorage.getItem(PENDING_KEY)===session?.user?.id;el('simpleContent').innerHTML=`<p class="sync-panel-intro">Acompanhe o salvamento do estoque e sincronize os aparelhos conectados à mesma conta.</p><div class="sync-details-grid"><div><small>STATUS ATUAL</small><b id="syncDetailsStatus">${escapeHtml(syncMessage)}</b></div><div><small>ÚLTIMA CONFIRMAÇÃO</small><b id="syncDetailsLast">${formatSyncDate(localStorage.getItem(LAST_SYNC_KEY))}</b></div><div><small>CONTA CONECTADA</small><b id="syncDetailsAccount">${escapeHtml(session?.user?.email||'Nenhuma conta conectada')}</b></div><div><small>ALTERAÇÕES NESTE APARELHO</small><b id="syncDetailsPending">${pending?'Aguardando confirmação':'Nenhuma pendente'}</b></div></div><div class="sync-panel-actions">${logged?'<button class="primary-btn" id="syncNowBtn">Sincronizar agora</button><button class="secondary-btn" id="syncBackupBtn">Baixar backup</button><button class="secondary-btn" id="syncLogoutBtn">Sair da conta</button>':'<button class="primary-btn" id="syncLoginBtn">Conectar uma conta</button><button class="secondary-btn" id="syncBackupBtn">Baixar backup</button>'}</div>`;el('simpleOverlay').classList.remove('hidden');if(logged){el('syncNowBtn').onclick=async()=>{await connectSync();syncPanel()};el('syncLogoutBtn').onclick=async()=>{try{const {error}=await supabaseClient.auth.signOut();if(error)throw error;session=null;setSyncStatus('offline','Entre na conta para sincronizar');syncPanel()}catch(error){notify(error.message||'Não foi possível desconectar.')}}}else el('syncLoginBtn').onclick=settings;el('syncBackupBtn').onclick=()=>el('exportBtn').click();setSyncStatus(syncStatus,syncMessage)}
function settings(){el('simpleEyebrow').textContent='PREFERÊNCIAS';el('simpleTitle').textContent='Configurações';const logged=Boolean(session?.user);el('simpleContent').innerHTML=logged?`<div class="setting-block"><h3>Conta Supabase</h3><p>Conta conectada: <b>${escapeHtml(session.user.email||'')}</b></p><button class="secondary-btn" id="settingsLogoutBtn">Sair da conta</button></div><div class="setting-block"><h3>Backup e privacidade</h3><p>Os dados ficam neste aparelho enquanto a sincronização não estiver disponível. Use o botão de download para guardar uma cópia.</p><button class="secondary-btn" id="settingsBackupBtn">Baixar backup</button></div>`:`<div class="setting-block"><h3>Sincronização entre aparelhos</h3><p>Entre com a mesma conta nos seus aparelhos para manter o estoque sincronizado.</p><input class="setting-input" id="sbEmail" type="email" autocomplete="email" placeholder="Seu e-mail"><input class="setting-input" id="sbPass" type="password" autocomplete="current-password" placeholder="Senha"><div class="modal-actions" style="margin-top:12px"><button class="secondary-btn" id="sbSignup">Criar conta</button><button class="primary-btn" id="sbLogin">Entrar e sincronizar</button></div></div><div class="setting-block"><h3>Backup</h3><p>Baixe uma cópia dos seus dados e fotos para guardar.</p><button class="secondary-btn" id="settingsBackupBtn">Baixar backup</button></div>`;el('simpleOverlay').classList.remove('hidden');el('settingsBackupBtn').onclick=()=>el('exportBtn').click();if(logged){el('settingsLogoutBtn').onclick=async()=>{try{const {error}=await supabaseClient.auth.signOut();if(error)throw error;session=null;setSyncStatus('offline','Entre na conta para sincronizar');settings()}catch(error){notify(error.message||'Não foi possível desconectar.')}}}else{el('sbSignup').onclick=async()=>{if(!configureSupabase())return;const email=el('sbEmail').value.trim(),password=el('sbPass').value;if(!email||!password)return notify('Preencha seu e-mail e sua senha.');try{const {data,error}=await supabaseClient.auth.signUp({email,password,options:{emailRedirectTo:location.origin+location.pathname}});if(error)throw error;if(data.session){session=data.session;await connectSync();syncPanel()}else notify('Conta criada. Confirme o e-mail e depois entre.')}catch(error){notify(error.message||'Não foi possível criar a conta.')}};el('sbLogin').onclick=async()=>{if(!configureSupabase())return;const email=el('sbEmail').value.trim(),password=el('sbPass').value;if(!email||!password)return notify('Preencha seu e-mail e sua senha.');try{const {data,error}=await supabaseClient.auth.signInWithPassword({email,password});if(error)throw error;session=data.session;await connectSync();syncPanel()}catch(error){notify(error.message||'Não foi possível entrar.')}}}}
el('settingsBtn').onclick=settings;render();initializeSync();
